    // 坐标映射
    const X0 = 60, X1 = 660, Y0 = 20, Y1 = 280;
    const xScale = (s) => X0 + (s / 100) * (X1 - X0);
    const yScale = (lr) => Y1 - (lr / 0.2) * (Y1 - Y0);

    // 计算三条曲线在给定步数的值
    function computeLR(s) {
      const stepDecay = 0.1 * Math.pow(0.5, Math.floor(s / 20));
      const cosine = 0.1 * 0.5 * (1 + Math.cos(Math.PI * s / 100));
      const warmup = 0.1 * Math.min(1, s / 10) * Math.pow(0.5, Math.floor(s / 20));
      return { step: stepDecay, cosine, warmup };
    }

    // 生成路径 d 属性 (0..s 步)
    function buildPathData(s, type) {
      if (s < 0) s = 0;
      const points = [];
      const maxDraw = Math.min(s, 100);
      for (let i = 0; i <= maxDraw; i++) {
        const lr = computeLR(i);
        const val = type === 'step' ? lr.step : type === 'cosine' ? lr.cosine : lr.warmup;
        points.push([xScale(i), yScale(val)]);
      }
      if (points.length === 0) return '';
      let d = `M ${points[0][0]} ${points[0][1]}`;
      for (let i = 1; i < points.length; i++) {
        d += ` L ${points[i][0]} ${points[i][1]}`;
      }
      return d;
    }

