      lrStep = vals.step;
      lrCosine = vals.cosine;
      lrWarmup = vals.warmup;

      pathStep.setAttribute('d', buildPathData(step, 'step'));
      pathCosine.setAttribute('d', buildPathData(step, 'cosine'));
