      const ix = xScale(step);
      indicatorLine.setAttribute('x1', ix);
      indicatorLine.setAttribute('x2', ix);

      labelStep.textContent = lrStep.toFixed(3);
      labelCosine.textContent = lrCosine.toFixed(3);
      labelWarmup.textContent = lrWarmup.toFixed(3);

